import os

def read_within(base_dir, user_path):
    """Return the text of base_dir/user_path, or '' if it cannot be read
    or escapes base_dir."""
    full = os.path.join(base_dir, user_path)
    try:
        with open(full) as f:
            return f.read()
    except OSError:
        return ''
